int ff_parse_mpeg2_descriptor(AVFormatContext *fc, AVStream *st, int stream_type,

                              const uint8_t **pp, const uint8_t *desc_list_end,

                              Mp4Descr *mp4_descr, int mp4_descr_count, int pid,

                              MpegTSContext *ts)

{

    const uint8_t *desc_end;

    int desc_len, desc_tag, desc_es_id;

    char language[252];

    int i;



    desc_tag = get8(pp, desc_list_end);

    if (desc_tag < 0)

        return AVERROR_INVALIDDATA;

    desc_len = get8(pp, desc_list_end);

    if (desc_len < 0)

        return AVERROR_INVALIDDATA;

    desc_end = *pp + desc_len;

    if (desc_end > desc_list_end)

        return AVERROR_INVALIDDATA;



    av_dlog(fc, "tag: 0x%02x len=%d\n", desc_tag, desc_len);



    if (st->codec->codec_id == AV_CODEC_ID_NONE &&

        stream_type == STREAM_TYPE_PRIVATE_DATA)

        mpegts_find_stream_type(st, desc_tag, DESC_types);



    switch (desc_tag) {

    case 0x1E: /* SL descriptor */

        desc_es_id = get16(pp, desc_end);

        if (ts && ts->pids[pid])

            ts->pids[pid]->es_id = desc_es_id;

        for (i = 0; i < mp4_descr_count; i++)

            if (mp4_descr[i].dec_config_descr_len &&

                mp4_descr[i].es_id == desc_es_id) {

                AVIOContext pb;

                ffio_init_context(&pb, mp4_descr[i].dec_config_descr,

                                  mp4_descr[i].dec_config_descr_len, 0,

                                  NULL, NULL, NULL, NULL);

                ff_mp4_read_dec_config_descr(fc, st, &pb);

                if (st->codec->codec_id == AV_CODEC_ID_AAC &&

                    st->codec->extradata_size > 0)

                    st->need_parsing = 0;

                if (st->codec->codec_id == AV_CODEC_ID_MPEG4SYSTEMS)

                    mpegts_open_section_filter(ts, pid, m4sl_cb, ts, 1);

            }

        break;

    case 0x1F: /* FMC descriptor */

        get16(pp, desc_end);

        if (mp4_descr_count > 0 &&

            st->codec->codec_id == AV_CODEC_ID_AAC_LATM &&

            mp4_descr->dec_config_descr_len && mp4_descr->es_id == pid) {

            AVIOContext pb;

            ffio_init_context(&pb, mp4_descr->dec_config_descr,

                              mp4_descr->dec_config_descr_len, 0,

                              NULL, NULL, NULL, NULL);

            ff_mp4_read_dec_config_descr(fc, st, &pb);

            if (st->codec->codec_id == AV_CODEC_ID_AAC &&

                st->codec->extradata_size > 0)

                st->need_parsing = 0;

        }

        break;

    case 0x56: /* DVB teletext descriptor */

        language[0] = get8(pp, desc_end);

        language[1] = get8(pp, desc_end);

        language[2] = get8(pp, desc_end);

        language[3] = 0;

        av_dict_set(&st->metadata, "language", language, 0);

        break;

    case 0x59: /* subtitling descriptor */

        language[0] = get8(pp, desc_end);

        language[1] = get8(pp, desc_end);

        language[2] = get8(pp, desc_end);

        language[3] = 0;

        /* hearing impaired subtitles detection */

        switch (get8(pp, desc_end)) {

        case 0x20: /* DVB subtitles (for the hard of hearing) with no monitor aspect ratio criticality */

        case 0x21: /* DVB subtitles (for the hard of hearing) for display on 4:3 aspect ratio monitor */

        case 0x22: /* DVB subtitles (for the hard of hearing) for display on 16:9 aspect ratio monitor */

        case 0x23: /* DVB subtitles (for the hard of hearing) for display on 2.21:1 aspect ratio monitor */

        case 0x24: /* DVB subtitles (for the hard of hearing) for display on a high definition monitor */

        case 0x25: /* DVB subtitles (for the hard of hearing) with plano-stereoscopic disparity for display on a high definition monitor */

            st->disposition |= AV_DISPOSITION_HEARING_IMPAIRED;

            break;

        }

        if (st->codec->extradata) {

            if (st->codec->extradata_size == 4 &&

                memcmp(st->codec->extradata, *pp, 4))

                avpriv_request_sample(fc, "DVB sub with multiple IDs");

        } else {

            st->codec->extradata = av_malloc(4 + FF_INPUT_BUFFER_PADDING_SIZE);

            if (st->codec->extradata) {

                st->codec->extradata_size = 4;

                memcpy(st->codec->extradata, *pp, 4);

            }

        }

        *pp += 4;

        av_dict_set(&st->metadata, "language", language, 0);

        break;

    case 0x0a: /* ISO 639 language descriptor */

        for (i = 0; i + 4 <= desc_len; i += 4) {

            language[i + 0] = get8(pp, desc_end);

            language[i + 1] = get8(pp, desc_end);

            language[i + 2] = get8(pp, desc_end);

            language[i + 3] = ',';

            switch (get8(pp, desc_end)) {

            case 0x01:

                st->disposition |= AV_DISPOSITION_CLEAN_EFFECTS;

                break;

            case 0x02:

                st->disposition |= AV_DISPOSITION_HEARING_IMPAIRED;

                break;

            case 0x03:

                st->disposition |= AV_DISPOSITION_VISUAL_IMPAIRED;

                break;

            }

        }

        if (i && language[0]) {

            language[i - 1] = 0;

            av_dict_set(&st->metadata, "language", language, 0);

        }

        break;

    case 0x05: /* registration descriptor */

        st->codec->codec_tag = bytestream_get_le32(pp);

        av_dlog(fc, "reg_desc=%.4s\n", (char *)&st->codec->codec_tag);

        if (st->codec->codec_id == AV_CODEC_ID_NONE)

            mpegts_find_stream_type(st, st->codec->codec_tag, REGD_types);

        break;

    default:

        break;

    }

    *pp = desc_end;

    return 0;

}

static int init_er(MpegEncContext *s)

{

    ERContext *er = &s->er;

    int mb_array_size = s->mb_height * s->mb_stride;

    int i;



    er->avctx       = s->avctx;

    er->mecc        = &s->mecc;



    er->mb_index2xy = s->mb_index2xy;

    er->mb_num      = s->mb_num;

    er->mb_width    = s->mb_width;

    er->mb_height   = s->mb_height;

    er->mb_stride   = s->mb_stride;

    er->b8_stride   = s->b8_stride;



    er->er_temp_buffer     = av_malloc(s->mb_height * s->mb_stride);

    er->error_status_table = av_mallocz(mb_array_size);

    if (!er->er_temp_buffer || !er->error_status_table)

        goto fail;



    er->mbskip_table  = s->mbskip_table;

    er->mbintra_table = s->mbintra_table;



    for (i = 0; i < FF_ARRAY_ELEMS(s->dc_val); i++)

        er->dc_val[i] = s->dc_val[i];



    er->decode_mb = mpeg_er_decode_mb;

    er->opaque    = s;



    return 0;

fail:

    av_freep(&er->er_temp_buffer);

    av_freep(&er->error_status_table);

    return AVERROR(ENOMEM);

}

static void pc_machine_set_max_ram_below_4g(Object *obj, Visitor *v,

                                            const char *name, void *opaque,

                                            Error **errp)

{

    PCMachineState *pcms = PC_MACHINE(obj);

    Error *error = NULL;

    uint64_t value;



    visit_type_size(v, name, &value, &error);

    if (error) {

        error_propagate(errp, error);

        return;

    }

    if (value > (1ULL << 32)) {

        error_setg(&error,

                   "Machine option 'max-ram-below-4g=%"PRIu64

                   "' expects size less than or equal to 4G", value);

        error_propagate(errp, error);

        return;

    }



    if (value < (1ULL << 20)) {

        error_report("Warning: small max_ram_below_4g(%"PRIu64

                     ") less than 1M.  BIOS may not work..",

                     value);

    }



    pcms->max_ram_below_4g = value;

}

void net_rx_pkt_attach_data(struct NetRxPkt *pkt, const void *data,

                               size_t len, bool strip_vlan)

{

    uint16_t tci = 0;

    uint16_t ploff;

    assert(pkt);

    pkt->vlan_stripped = false;



    if (strip_vlan) {

        pkt->vlan_stripped = eth_strip_vlan(data, pkt->ehdr_buf, &ploff, &tci);

    }



    if (pkt->vlan_stripped) {

        pkt->vec[0].iov_base = pkt->ehdr_buf;

        pkt->vec[0].iov_len = ploff - sizeof(struct vlan_header);

        pkt->vec[1].iov_base = (uint8_t *) data + ploff;

        pkt->vec[1].iov_len = len - ploff;

        pkt->vec_len = 2;

        pkt->tot_len = len - ploff + sizeof(struct eth_header);

    } else {

        pkt->vec[0].iov_base = (void *)data;

        pkt->vec[0].iov_len = len;

        pkt->vec_len = 1;

        pkt->tot_len = len;

    }



    pkt->tci = tci;

}

e1000_receive(NetClientState *nc, const uint8_t *buf, size_t size)

{

    E1000State *s = qemu_get_nic_opaque(nc);

    struct e1000_rx_desc desc;

    dma_addr_t base;

    unsigned int n, rdt;

    uint32_t rdh_start;

    uint16_t vlan_special = 0;

    uint8_t vlan_status = 0, vlan_offset = 0;

    uint8_t min_buf[MIN_BUF_SIZE];

    size_t desc_offset;

    size_t desc_size;

    size_t total_size;



    if (!(s->mac_reg[RCTL] & E1000_RCTL_EN))

        return -1;



    /* Pad to minimum Ethernet frame length */

    if (size < sizeof(min_buf)) {

        memcpy(min_buf, buf, size);

        memset(&min_buf[size], 0, sizeof(min_buf) - size);

        buf = min_buf;

        size = sizeof(min_buf);

    }



    /* Discard oversized packets if !LPE and !SBP. */

    if ((size > MAXIMUM_ETHERNET_LPE_SIZE ||

        (size > MAXIMUM_ETHERNET_VLAN_SIZE

        && !(s->mac_reg[RCTL] & E1000_RCTL_LPE)))

        && !(s->mac_reg[RCTL] & E1000_RCTL_SBP)) {

        return size;

    }



    if (!receive_filter(s, buf, size))

        return size;



    if (vlan_enabled(s) && is_vlan_packet(s, buf)) {

        vlan_special = cpu_to_le16(be16_to_cpup((uint16_t *)(buf + 14)));

        memmove((uint8_t *)buf + 4, buf, 12);

        vlan_status = E1000_RXD_STAT_VP;

        vlan_offset = 4;

        size -= 4;

    }



    rdh_start = s->mac_reg[RDH];

    desc_offset = 0;

    total_size = size + fcs_len(s);

    if (!e1000_has_rxbufs(s, total_size)) {

            set_ics(s, 0, E1000_ICS_RXO);

            return -1;

    }

    do {

        desc_size = total_size - desc_offset;

        if (desc_size > s->rxbuf_size) {

            desc_size = s->rxbuf_size;

        }

        base = rx_desc_base(s) + sizeof(desc) * s->mac_reg[RDH];

        pci_dma_read(&s->dev, base, &desc, sizeof(desc));

        desc.special = vlan_special;

        desc.status |= (vlan_status | E1000_RXD_STAT_DD);

        if (desc.buffer_addr) {

            if (desc_offset < size) {

                size_t copy_size = size - desc_offset;

                if (copy_size > s->rxbuf_size) {

                    copy_size = s->rxbuf_size;

                }

                pci_dma_write(&s->dev, le64_to_cpu(desc.buffer_addr),

                              buf + desc_offset + vlan_offset, copy_size);

            }

            desc_offset += desc_size;

            desc.length = cpu_to_le16(desc_size);

            if (desc_offset >= total_size) {

                desc.status |= E1000_RXD_STAT_EOP | E1000_RXD_STAT_IXSM;

            } else {

                /* Guest zeroing out status is not a hardware requirement.

                   Clear EOP in case guest didn't do it. */

                desc.status &= ~E1000_RXD_STAT_EOP;

            }

        } else { // as per intel docs; skip descriptors with null buf addr

            DBGOUT(RX, "Null RX descriptor!!\n");

        }

        pci_dma_write(&s->dev, base, &desc, sizeof(desc));



        if (++s->mac_reg[RDH] * sizeof(desc) >= s->mac_reg[RDLEN])

            s->mac_reg[RDH] = 0;

        /* see comment in start_xmit; same here */

        if (s->mac_reg[RDH] == rdh_start) {

            DBGOUT(RXERR, "RDH wraparound @%x, RDT %x, RDLEN %x\n",

                   rdh_start, s->mac_reg[RDT], s->mac_reg[RDLEN]);

            set_ics(s, 0, E1000_ICS_RXO);

            return -1;

        }

    } while (desc_offset < total_size);



    s->mac_reg[GPRC]++;

    s->mac_reg[TPR]++;

    /* TOR - Total Octets Received:

     * This register includes bytes received in a packet from the <Destination

     * Address> field through the <CRC> field, inclusively.

     */

    n = s->mac_reg[TORL] + size + /* Always include FCS length. */ 4;

    if (n < s->mac_reg[TORL])

        s->mac_reg[TORH]++;

    s->mac_reg[TORL] = n;



    n = E1000_ICS_RXT0;

    if ((rdt = s->mac_reg[RDT]) < s->mac_reg[RDH])

        rdt += s->mac_reg[RDLEN] / sizeof(desc);

    if (((rdt - s->mac_reg[RDH]) * sizeof(desc)) <= s->mac_reg[RDLEN] >>

        s->rxbuf_min_shift)

        n |= E1000_ICS_RXDMT0;



    set_ics(s, 0, n);



    return size;

}

void ppce500_init(QEMUMachineInitArgs *args, PPCE500Params *params)

{

    MemoryRegion *address_space_mem = get_system_memory();

    MemoryRegion *ram = g_new(MemoryRegion, 1);

    PCIBus *pci_bus;

    CPUPPCState *env = NULL;

    uint64_t elf_entry;

    uint64_t elf_lowaddr;

    hwaddr entry=0;

    hwaddr loadaddr=UIMAGE_LOAD_BASE;

    target_long kernel_size=0;

    target_ulong dt_base = 0;

    target_ulong initrd_base = 0;

    target_long initrd_size = 0;

    target_ulong cur_base = 0;

    int i;

    unsigned int pci_irq_nrs[4] = {1, 2, 3, 4};

    qemu_irq **irqs, *mpic;

    DeviceState *dev;

    CPUPPCState *firstenv = NULL;

    MemoryRegion *ccsr_addr_space;

    SysBusDevice *s;

    PPCE500CCSRState *ccsr;



    /* Setup CPUs */

    if (args->cpu_model == NULL) {

        args->cpu_model = "e500v2_v30";

    }



    irqs = g_malloc0(smp_cpus * sizeof(qemu_irq *));

    irqs[0] = g_malloc0(smp_cpus * sizeof(qemu_irq) * OPENPIC_OUTPUT_NB);

    for (i = 0; i < smp_cpus; i++) {

        PowerPCCPU *cpu;

        CPUState *cs;

        qemu_irq *input;



        cpu = cpu_ppc_init(args->cpu_model);

        if (cpu == NULL) {

            fprintf(stderr, "Unable to initialize CPU!\n");

            exit(1);

        }

        env = &cpu->env;

        cs = CPU(cpu);



        if (!firstenv) {

            firstenv = env;

        }



        irqs[i] = irqs[0] + (i * OPENPIC_OUTPUT_NB);

        input = (qemu_irq *)env->irq_inputs;

        irqs[i][OPENPIC_OUTPUT_INT] = input[PPCE500_INPUT_INT];

        irqs[i][OPENPIC_OUTPUT_CINT] = input[PPCE500_INPUT_CINT];

        env->spr[SPR_BOOKE_PIR] = cs->cpu_index = i;

        env->mpic_iack = MPC8544_CCSRBAR_BASE +

                         MPC8544_MPIC_REGS_OFFSET + 0xa0;



        ppc_booke_timers_init(cpu, 400000000, PPC_TIMER_E500);



        /* Register reset handler */

        if (!i) {

            /* Primary CPU */

            struct boot_info *boot_info;

            boot_info = g_malloc0(sizeof(struct boot_info));

            qemu_register_reset(ppce500_cpu_reset, cpu);

            env->load_info = boot_info;

        } else {

            /* Secondary CPUs */

            qemu_register_reset(ppce500_cpu_reset_sec, cpu);

        }

    }



    env = firstenv;



    /* Fixup Memory size on a alignment boundary */

    ram_size &= ~(RAM_SIZES_ALIGN - 1);

    args->ram_size = ram_size;



    /* Register Memory */

    memory_region_init_ram(ram, NULL, "mpc8544ds.ram", ram_size);

    vmstate_register_ram_global(ram);

    memory_region_add_subregion(address_space_mem, 0, ram);



    dev = qdev_create(NULL, "e500-ccsr");

    object_property_add_child(qdev_get_machine(), "e500-ccsr",

                              OBJECT(dev), NULL);

    qdev_init_nofail(dev);

    ccsr = CCSR(dev);

    ccsr_addr_space = &ccsr->ccsr_space;

    memory_region_add_subregion(address_space_mem, MPC8544_CCSRBAR_BASE,

                                ccsr_addr_space);



    mpic = ppce500_init_mpic(params, ccsr_addr_space, irqs);



    /* Serial */

    if (serial_hds[0]) {

        serial_mm_init(ccsr_addr_space, MPC8544_SERIAL0_REGS_OFFSET,

                       0, mpic[42], 399193,

                       serial_hds[0], DEVICE_BIG_ENDIAN);

    }



    if (serial_hds[1]) {

        serial_mm_init(ccsr_addr_space, MPC8544_SERIAL1_REGS_OFFSET,

                       0, mpic[42], 399193,

                       serial_hds[1], DEVICE_BIG_ENDIAN);

    }



    /* General Utility device */

    dev = qdev_create(NULL, "mpc8544-guts");

    qdev_init_nofail(dev);

    s = SYS_BUS_DEVICE(dev);

    memory_region_add_subregion(ccsr_addr_space, MPC8544_UTIL_OFFSET,

                                sysbus_mmio_get_region(s, 0));



    /* PCI */

    dev = qdev_create(NULL, "e500-pcihost");

    qdev_prop_set_uint32(dev, "first_slot", params->pci_first_slot);

    qdev_init_nofail(dev);

    s = SYS_BUS_DEVICE(dev);

    sysbus_connect_irq(s, 0, mpic[pci_irq_nrs[0]]);

    sysbus_connect_irq(s, 1, mpic[pci_irq_nrs[1]]);

    sysbus_connect_irq(s, 2, mpic[pci_irq_nrs[2]]);

    sysbus_connect_irq(s, 3, mpic[pci_irq_nrs[3]]);

    memory_region_add_subregion(ccsr_addr_space, MPC8544_PCI_REGS_OFFSET,

                                sysbus_mmio_get_region(s, 0));



    pci_bus = (PCIBus *)qdev_get_child_bus(dev, "pci.0");

    if (!pci_bus)

        printf("couldn't create PCI controller!\n");



    sysbus_mmio_map(SYS_BUS_DEVICE(dev), 1, MPC8544_PCI_IO);



    if (pci_bus) {

        /* Register network interfaces. */

        for (i = 0; i < nb_nics; i++) {

            pci_nic_init_nofail(&nd_table[i], pci_bus, "virtio", NULL);

        }

    }



    /* Register spinning region */

    sysbus_create_simple("e500-spin", MPC8544_SPIN_BASE, NULL);



    /* Load kernel. */

    if (args->kernel_filename) {

        kernel_size = load_uimage(args->kernel_filename, &entry,

                                  &loadaddr, NULL);

        if (kernel_size < 0) {

            kernel_size = load_elf(args->kernel_filename, NULL, NULL,

                                   &elf_entry, &elf_lowaddr, NULL, 1,

                                   ELF_MACHINE, 0);

            entry = elf_entry;

            loadaddr = elf_lowaddr;

        }

        /* XXX try again as binary */

        if (kernel_size < 0) {

            fprintf(stderr, "qemu: could not load kernel '%s'\n",

                    args->kernel_filename);

            exit(1);

        }



        cur_base = loadaddr + kernel_size;



        /* Reserve space for dtb */

        dt_base = (cur_base + DTC_LOAD_PAD) & ~DTC_PAD_MASK;

        cur_base += DTB_MAX_SIZE;

    }



    /* Load initrd. */

    if (args->initrd_filename) {

        initrd_base = (cur_base + INITRD_LOAD_PAD) & ~INITRD_PAD_MASK;

        initrd_size = load_image_targphys(args->initrd_filename, initrd_base,

                                          ram_size - initrd_base);



        if (initrd_size < 0) {

            fprintf(stderr, "qemu: could not load initial ram disk '%s'\n",

                    args->initrd_filename);

            exit(1);

        }



        cur_base = initrd_base + initrd_size;

    }



    /* If we're loading a kernel directly, we must load the device tree too. */

    if (args->kernel_filename) {

        struct boot_info *boot_info;

        int dt_size;



        dt_size = ppce500_load_device_tree(env, args, params, dt_base,

                                           initrd_base, initrd_size);

        if (dt_size < 0) {

            fprintf(stderr, "couldn't load device tree\n");

            exit(1);

        }

        assert(dt_size < DTB_MAX_SIZE);



        boot_info = env->load_info;

        boot_info->entry = entry;

        boot_info->dt_base = dt_base;

        boot_info->dt_size = dt_size;

    }



    if (kvm_enabled()) {

        kvmppc_init();

    }

}

