static void mdct512(int32_t *out, int16_t *in)

{

    int i, re, im, re1, im1;

    int16_t rot[MDCT_SAMPLES];

    IComplex x[MDCT_SAMPLES/4];



    /* shift to simplify computations */

    for (i = 0; i < MDCT_SAMPLES/4; i++)

        rot[i] = -in[i + 3*MDCT_SAMPLES/4];

    for (;i < MDCT_SAMPLES; i++)

        rot[i] =  in[i -   MDCT_SAMPLES/4];



    /* pre rotation */

    for (i = 0; i < MDCT_SAMPLES/4; i++) {

        re =  ((int)rot[               2*i] - (int)rot[MDCT_SAMPLES  -1-2*i]) >> 1;

        im = -((int)rot[MDCT_SAMPLES/2+2*i] - (int)rot[MDCT_SAMPLES/2-1-2*i]) >> 1;

        CMUL(x[i].re, x[i].im, re, im, -xcos1[i], xsin1[i]);

    }



    fft(x, MDCT_NBITS - 2);



    /* post rotation */

    for (i = 0; i < MDCT_SAMPLES/4; i++) {

        re = x[i].re;

        im = x[i].im;

        CMUL(re1, im1, re, im, xsin1[i], xcos1[i]);

        out[                 2*i] = im1;

        out[MDCT_SAMPLES/2-1-2*i] = re1;

    }

}

void helper_iret_real(int shift)

{

    uint32_t sp, new_cs, new_eip, new_eflags, new_esp;

    uint8_t *ssp;

    int eflags_mask;



    sp = env->regs[R_ESP] & 0xffff;

    ssp = env->segs[R_SS].base + sp;

    if (shift == 1) {

        /* 32 bits */

        new_eflags = ldl(ssp + 8);

        new_cs = ldl(ssp + 4) & 0xffff;

        new_eip = ldl(ssp) & 0xffff;

    } else {

        /* 16 bits */

        new_eflags = lduw(ssp + 4);

        new_cs = lduw(ssp + 2);

        new_eip = lduw(ssp);

    }

    new_esp = sp + (6 << shift);

    env->regs[R_ESP] = (env->regs[R_ESP] & 0xffff0000) | 

        (new_esp & 0xffff);

    load_seg_vm(R_CS, new_cs);

    env->eip = new_eip;

    eflags_mask = FL_UPDATE_CPL0_MASK;

    if (shift == 0)

        eflags_mask &= 0xffff;

    load_eflags(new_eflags, eflags_mask);

}

